// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        admin = address(this);
        c = new C();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(caller);
        bool result;
        if (caller == admin) {
            result = c.setOwner(newOwner);
            assertTrue(result);
        } else {
            // Expect revert (the correct version reverts if caller is not admin)
            vm.expectRevert("Only admin can call address(this) function");
            c.setOwner(newOwner);
        }
    }
}

